#!/usr/bin/env python3
"""Add a readable fixed 50-draw study and timestamped rows to the existing audit."""
import argparse,datetime as dt,html,json,os,re
from pathlib import Path
E=html.escape
GAMES=[('EuroJackpot','EuroJackpot'),('Lotto','Lotto'),('Vikinglotto','Vikinglotto'),('LotteryAudit','Lottery Audit')]
def nav(current):return '<nav class="lab-tabs" aria-label="Number labs">'+''.join(f'<a href="/{folder}/"'+(' aria-current="page"' if folder==current else '')+f'>{label}</a>' for folder,label in GAMES)+'</nav>'
def read_js(p):return json.loads(p.read_text().split('=',1)[1].strip().rstrip(';'))
def atomic(p,text):
 t=p.with_suffix(p.suffix+'.audit-tmp');t.write_text(text);os.chmod(t,0o644);os.replace(t,p)
def balls(nums,star=False):return ''.join(f'<span class="ball'+(' s' if star else '')+f'">{x}</span>' for x in nums)
def line(r):return '–'.join(map(str,r['main']))+' + '+'–'.join(map(str,r['stars']))
def markers(text,name,content):
 a=f'<!-- {name}_START -->';b=f'<!-- {name}_END -->';assert text.count(a)==1 and text.count(b)==1
 return re.sub(re.escape(a)+r'.*?'+re.escape(b),lambda _:a+content+b,text,flags=re.S)
def render(root):
 out=root/'LotteryAudit';report=json.loads((out/'inverse-50-20261020.json').read_text());s=report['summary'];history=read_js(root/'EuroJackpot/history.js')['draws'];last=history[-1]['date'];registrations=[]
 for file,prefix,kind in [('proposals.js','window.EJ_PROPOSALS=','original'),('comparison-forecasts.json','','uniform'),('inverse-forecasts.json','','inverse')]:
  p=root/'EuroJackpot'/file
  if not p.exists():continue
  data=read_js(p) if prefix else json.loads(p.read_text())
  for f in data['forecasts']:
   if f['date']<=last or kind=='original' and f['mode']!='model':continue
   for i,r in enumerate(f['rows']):registrations.append({'date':f['date'],'kind':kind,'label':('Original AI '+str(i+1) if kind=='original' else 'Uniform comparison '+str(i+1) if kind=='uniform' else 'Frozen inverse quadratic'), 'main':r['main'],'stars':r['stars'],'createdAt':f['createdAt'],'asOf':f['asOf'],'featureCutoff':f.get('featureCutoff'),'fitLabelDate':f.get('fitLabelDate'),'informationKnownThrough':f.get('informationKnownThrough',f['asOf'])})
 target=min(r['date'] for r in registrations);registrations=[r for r in registrations if r['date']==target]
 atomic(out/'registered-suggestions.json',json.dumps({'targetDate':target,'rows':registrations,'note':'Historical fits are not registered predictions. These records were saved before the target draw; original records are preserved.'},indent=2)+'\n')
 def card(r):return f'<article class="card"><strong>{E(r["label"])}</strong><div class="row">'+balls(r['main'])+'<span class="small">+</span>'+balls(r['stars'],True)+f'</div><p class="small">Registered {E(r["createdAt"])} · feature history through {r["asOf"]}'+(f' · coefficients fitted using the {r["fitLabelDate"]} answer' if r.get('fitLabelDate') else '')+'</p></article>'
 current=f'<section id="saved-suggestions"><h2>Saved suggestions · EuroJackpot · {target}</h2><p>These are saved selections for the next draw, separate from the popularity generator below. The original AI forecasts remain unchanged.</p>'+''.join(card(r) for r in registrations if r['kind']!='original')+'<details class="card"><summary>Original AI selections for the same draw</summary>'+''.join(card(r) for r in registrations if r['kind']=='original')+'</details><p class="small">The inverse row uses the same fixed coefficients that were fitted to the known 20 October answer. Its features stop seven days before the target, but its coefficients were learned after that cutoff. This is a new prospective experiment, not a prediction made a week early. No prediction advantage has been established.</p><p><a href="/EuroJackpot/#trekninger">Open the complete EuroJackpot ticket</a> · <a href="registered-suggestions.json">Inspect saved rows and timestamps</a></p></section>'
 rows=[]
 for r in reversed(report['draws']):
  fitted=r['answerRefit'];degrees=[fitted[field]['fit']['weightCount'] if fitted[field]['fit'] else None for field in ['main','stars']];result='5+2 (answer fitted)' if fitted['exactBoth'] else 'Not separated'
  rows.append(f'<tr><td>{r["date"]}<br><small>cutoff {r["cutoffDate"]}</small></td><td>{r["available"]["main"]["asOf"]}<br><small>{r["available"]["main"]["count"]} main / {r["available"]["stars"]["count"]} Euro draws</small></td><td class="num">{line(r["actual"])}</td><td class="num">{line(r["frozen"])}</td><td class="num">{r["frozen"]["hits"]["main"]}+{r["frozen"]["hits"]["stars"]}</td><td>{result}<br><small>{degrees[0]} main / {degrees[1]} Euro weights</small></td></tr>')
 study=f'''<section id="inverse-study"><h2>50 draws · can an answer-fitted method repeat?</h2><p>{s['from']} to {s['through']}. Every feature calculation stops seven calendar days before its target draw, using the latest published draw on or before that date.</p><div class="study-summary"><article class="card"><span class="pill warn">New weights for every answer</span><h3>{s['refittedExactBoth']} / 50 exact fits</h3><p>The winning numbers were used to choose each draw’s coefficients. This demonstrates hindsight fitting, not 50 successful predictions.</p></article><article class="card"><span class="pill">Same original coefficients</span><h3>{s['frozenOtherFullMatches']} / {s['frozenOtherDraws']} full matches on other draws</h3><p>The only 5+2 fit among all 50 is 20 October, the answer that supplied these coefficients. It is excluded from this comparison.</p></article></div><div class="card verdict"><strong>Same formula family does not mean the same predictive rule.</strong><p>For the main pool, {s['degreeCounts']['main']['2']} cases fit with 9 quadratic weights and {s['degreeCounts']['main']['3']} needed 19 cubic weights. Euro numbers used 9 weights in all 50 cases. The coefficients were refitted separately to each known answer.</p><p>We also tested a single common coefficient set across all 50 cases, with 9, 19 and 34 terms. None of these tested common-weight models could rank every winning set strictly above its non-winners.</p></div><details class="card"><summary>Calculation and limits</summary><p>Three inputs per number: last-50 frequency, long-run frequency shrunk with a 30-draw prior, and absence scaled to the pool. Standardised features are clipped, then expanded into products and powers. A linear-programming solver chooses coefficients to maximise the strict score margin between known winners and non-winners. Degree 2, 3 and 4 were tried in that order, stopping at the first exact fit; ties use ascending number order.</p><p>Using the original fixed 20 October coefficients gives {s['frozenMainHits']} main and {s['frozenStarHits']} Euro-number matches over all 50 cases. Excluding the case used to fit the model, the mean is {s['frozenOtherMeanHits']:.3f} individual-number matches per line over {s['frozenOtherDraws']} other draws. The fair-draw expectation is {s['uniformExpectedMean']:.3f}. This retrospective diagnostic was built after outcomes were known and is not an independent validation or a demonstrated increase in jackpot probability.</p><p>Only prospective results after the coefficients and selections are registered can test the new fixed rule without this direct answer fitting.</p></details><div class="card tablewrap"><table id="inverse-results"><thead><tr><th>Target / one-week cutoff</th><th>Feature history available</th><th>Actual main + Euro</th><th>Same frozen rule: main + Euro</th><th>Frozen-rule hits</th><th>New fit to each answer</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div><p class="small">The last column’s selected numbers equal the actual numbers in every exact-fit case; full per-case coefficients and predictions are in the JSON record. Different coefficients per row must not be presented as one model predicting all 50 draws.</p><p><a href="inverse-50-20261020.json">Full 50-draw analysis and coefficients (JSON)</a> · <a href="inverse-50-20261020.csv">All 50 comparisons (CSV)</a> · <a href="inverse-model-20261020.json">Original fixed model</a></p></section>'''
 p=out/'index.html';page=p.read_text()
 if '<!-- AUDIT_NAV_START -->' not in page:page=page.replace('<main>','<main>\n<!-- AUDIT_NAV_START --><!-- AUDIT_NAV_END -->',1)
 if '<!-- INVERSE_STUDY_START -->' not in page:
  marker='<h2>1 · Does any method beat random?</h2>';assert marker in page
  page=page.replace(marker,'<!-- SAVED_SUGGESTIONS_START --><!-- SAVED_SUGGESTIONS_END -->\n<!-- INVERSE_STUDY_START --><!-- INVERSE_STUDY_END -->\n'+marker,1)
 if 'id="audit-navigation-style"' not in page:page=page.replace('</head>','<style id="audit-navigation-style">.lab-tabs{display:flex;flex-wrap:wrap;gap:9px;margin:0 0 30px}.lab-tabs a{border:1px solid var(--line);padding:9px 15px;border-radius:30px;text-decoration:none;color:var(--ink)}.lab-tabs a[aria-current]{background:var(--accent);border-color:var(--accent);color:#fff}.lab-tabs a:focus-visible{outline:3px solid var(--accent);outline-offset:3px}.study-summary{display:grid;grid-template-columns:1fr 1fr;gap:12px}.study-summary .card{margin:0}#inverse-study summary,#saved-suggestions summary{cursor:pointer;font-weight:600}#inverse-results small{color:var(--mute)}@media(max-width:600px){.study-summary{grid-template-columns:1fr}.lab-tabs{gap:7px}.lab-tabs a{font-size:14px;padding:9px 12px}}</style></head>',1)
 page=page.replace('Two honest questions about Lotto, Vikinglotto and EuroJackpot. Can anything in the archives predict the next draw? And can we at least avoid sharing a jackpot?','Official archives, saved selections and transparent tests of rules fitted to known answers. Explore the results and the limits of each experiment.')
 page=markers(page,'AUDIT_NAV',nav('LotteryAudit'));page=markers(page,'SAVED_SUGGESTIONS',current);page=markers(page,'INVERSE_STUDY',study);atomic(p,page)
 print(f'LotteryAudit rendered: {len(report["draws"])} audited draws, {len(registrations)} registered rows for {target}')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);render(p.parse_args().root)
